// utils/prototype/{prototype}/{Prototype}Template.ts
// Prototype — template clonable pour {Prototype}

// Interface Cloneable — tout prototype l'implémente
export interface Cloneable<T> {
  clone(): T
}

export class {Prototype}Template implements Cloneable<{Prototype}Template> {
  constructor(
    // Ajoute ici les champs du template
    // Exemple : public title: string = '', public content: string = ''
  ) {}

  // Clone superficiel — copie indépendante
  clone(): {Prototype}Template {
    return new {Prototype}Template(
      // Ajoute ici les champs à copier
    )
  }

  // Clone avec surcharges partielles — jamais de mutation du prototype original
  cloneWith(overrides: Partial<Record<string, unknown>>): {Prototype}Template {
    const cloned = this.clone()
    Object.assign(cloned, overrides)
    return cloned
  }

  // Convertit en payload pour l'API
  toPayload(): Record<string, unknown> {
    return {
      // Ajoute ici les champs du payload
    }
  }
}

