// Toujours cloner avant utilisation — jamais modifier directement
export const {PROTOTYPE}_TEMPLATES = {
  default: new {Prototype}Template(
    // Ajoute ici les valeurs du template par défaut
  ),
  // Ajoute ici d'autres templates prédéfinis
} as const

// composables/{prototype}/use{Prototype}Duplicate.ts
import { {Prototype}Template, {PROTOTYPE}_TEMPLATES } from '~/utils/prototype/{prototype}/{Prototype}Template'

export const use{Prototype}Duplicate = () => {
  // Crée un prototype depuis un objet existant
  const fromExisting = (item: Record<string, unknown>): {Prototype}Template => {
    return new {Prototype}Template(
      // Ajoute ici le mapping depuis l'objet existant
      // Exemple : `Copie de ${item.title}`, item.content
    )
  }

  // Duplique via le prototype — crée et envoie à l'API
  const duplicate = async (item: Record<string, unknown>) => {
    const template = fromExisting(item)
    // Ajoute ici l'appel à l'API
    // const { create } = use{Prototype}s()
    // return await create(template.toPayload())
    return template.toPayload()
  }

  // Initialise depuis un template pré-défini
  const fromTemplate = (key: keyof typeof {PROTOTYPE}_TEMPLATES) => {
    // Toujours cloner — jamais modifier le prototype original
    return {PROTOTYPE}_TEMPLATES[key].clone()
  }

  return { fromExisting, duplicate, fromTemplate }
}

// tests/utils/prototype/{prototype}/{Prototype}Template.spec.ts
import { describe, it, expect } from 'vitest'
import { {Prototype}Template, {PROTOTYPE}_TEMPLATES } from '~/utils/prototype/{prototype}/{Prototype}Template'

describe('{Prototype}Template', () => {

  describe('clone()', () => {
    it('retourne une instance indépendante', () => {
      const original = new {Prototype}Template()
      const cloned   = original.clone()
      expect(cloned).not.toBe(original)
    })

    it('la copie a les mêmes valeurs que l\'original', () => {
      const original = new {Prototype}Template()
      const cloned   = original.clone()
      expect(cloned.toPayload()).toEqual(original.toPayload())
    })

    it('modifier la copie ne modifie pas l\'original', () => {
      const original = new {Prototype}Template()
      const cloned   = original.clone()
      // Ajoute ici une modification sur cloned
      // cloned.someField = 'modified'
      // expect(original.someField).not.toBe('modified')
      expect(cloned).not.toBe(original)
    })
  })

  describe('cloneWith()', () => {
    it('applique les overrides sans modifier l\'original', () => {
      const original = new {Prototype}Template()
      const variant  = original.cloneWith({ /* overrides */ })
      expect(variant).not.toBe(original)
    })
  })

  describe('{PROTOTYPE}_TEMPLATES', () => {
    it('les templates pré-définis sont définis', () => {
      expect({PROTOTYPE}_TEMPLATES.default).toBeDefined()
    })

    it('cloner un template retourne une copie indépendante', () => {
      const clone = {PROTOTYPE}_TEMPLATES.default.clone()
      expect(clone).not.toBe({PROTOTYPE}_TEMPLATES.default)
    })
  })

  describe('toPayload()', () => {
    it('retourne un objet sérialisable', () => {
      const payload = new {Prototype}Template().toPayload()
      expect(typeof payload).toBe('object')
      expect(() => JSON.stringify(payload)).not.toThrow()
    })
  })

})
